<template><div class="auth-page"><section class="auth-card"><h1>Reset your password</h1><p>Enter the email used for your FigColor account.</p><form @submit.prevent="submit"><label>Email<input v-model="email" type="email" required autocomplete="email"></label><button :disabled="busy">{{busy?'Sending…':'Send reset link'}}</button></form></section></div></template>
<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{forgotPassword}from'@/api/auth';const email=ref(''),busy=ref(false),router=useRouter();async function submit(){busy.value=true;try{await forgotPassword(email.value);router.push('/forgot-password/sent')}finally{busy.value=false}}</script>
<style scoped>.auth-page{display:grid;place-items:center;min-height:60vh}.auth-card{width:min(400px,100%);border:1px solid var(--color-border);border-radius:var(--radius-lg);padding:2rem}form,label{display:flex;flex-direction:column;gap:.75rem}input,button{padding:.8rem;border-radius:var(--radius-md)}input{border:1px solid var(--color-border)}button{border:0;background:var(--color-primary);color:white}</style>
